-- bm Font: Advanced font editor for BareMetal (640x360)
-- Create, edit, and organize bitmap fonts in /bmf/ with .bmf extension.

local HEX_ORIG_8X16 = ""
local HEX_INTER_8X16 = ""
local HEX_6X12 = ""

-- Palette
local C = {
  bg = 0x0A0E14,
  panel = 0x141B24,
  panel_hi = 0x1E293B,
  border = 0x2D3748,
  border_hi = 0x4A5568,
  grid = 0x1F2937,
  grid_dot = 0x374151,
  pixel_on = 0x00E5FF,
  pixel_off = 0x111827,
  accent = 0xFF9100,
  text = 0xE2E8F0,
  dim = 0x64748B,
  btn = 0x1E293B,
  btn_hi = 0x334155,
  btn_text = 0xF1F5F9,
  cyan = 0x00E5FF,
  green = 0x10B981,
  yellow = 0xFBBF24,
  red = 0xEF4444,
  white = 0xFFFFFF,
  black = 0x000000,
}

local fonts = {}
local active_font_idx = 1
local cur_font = nil
local cur_char = 65 -- 'A'
local clipboard = nil

local notice = "bm Font pronto (/bmf)"
local notice_timer = 120

-- UI State
local preview_scale = 1 -- 1, 2, or 3
local dropdown_open = false
local new_modal_open = false
local new_font_size = "8x16"
local new_font_base = "inter"

local function set_notice(msg)
  notice = msg
  notice_timer = 150
end

local function parse_hex_glyphs(hex_str, height)
  local gl = {}
  local total_chars = 256
  local hex_len = #hex_str
  local expected = total_chars * height * 2
  local ptr = 1
  for i = 0, total_chars - 1 do
    gl[i] = {}
    for y = 1, height do
      if ptr + 1 <= hex_len then
        local b_str = hex_str:sub(ptr, ptr + 1)
        gl[i][y] = tonumber(b_str, 16) or 0
        ptr = ptr + 2
      else
        gl[i][y] = 0
      end
    end
  end
  return gl
end

local function load_bmf_data(stem, raw)
  if #raw < 32 then return nil end
  if raw:sub(1, 6) ~= "BMFONT" then return nil end
  local w = raw:byte(9)
  local h = raw:byte(10)
  local count = raw:byte(11) + raw:byte(12) * 256
  local name = raw:sub(17, 32):gsub("%z.*", "")
  if name == "" then name = stem end
  local gl = {}
  local ptr = 33
  for i = 0, count - 1 do
    gl[i] = {}
    for y = 1, h do
      gl[i][y] = raw:byte(ptr) or 0
      ptr = ptr + 1
    end
  end
  return { name = name, stem = stem, cw = w, ch = h, glyphs = gl }
end

local function pack_bmf(font)
  local magic = "BMFONT\1\0"
  local dims = string.char(font.cw, font.ch)
  local count = string.char(256 % 256, math.floor(256 / 256))
  local res = "\0\0\0\0"
  local n = (font.name or font.stem):sub(1, 15)
  local name_padded = n .. string.rep("\0", 16 - #n)
  local header = magic .. dims .. count .. res .. name_padded
  local bytes = {}
  for i = 0, 255 do
    local g = font.glyphs[i] or {}
    for y = 1, font.ch do
      table.insert(bytes, string.char(g[y] or 0))
    end
  end
  return header .. table.concat(bytes)
end

local function init_fonts()
  fonts = {}
  local loaded_any = false
  if font_list then
    local list = font_list()
    if list and #list > 0 then
      for _, item in ipairs(list) do
        local raw = font_read(item.name)
        if raw then
          local f = load_bmf_data(item.name, raw)
          if f then
            table.insert(fonts, f)
            loaded_any = true
          end
        end
      end
    end
  end

  if not loaded_any then
    table.insert(fonts, { name = "Terminus", stem = "terminus", cw = 8, ch = 16, glyphs = parse_hex_glyphs(HEX_ORIG_8X16, 16) })
    table.insert(fonts, { name = "Inter", stem = "inter", cw = 8, ch = 16, glyphs = parse_hex_glyphs(HEX_INTER_8X16, 16) })
    table.insert(fonts, { name = "6x12", stem = "6x12", cw = 6, ch = 12, glyphs = parse_hex_glyphs(HEX_6X12, 12) })
    if font_write then
      for _, f in ipairs(fonts) do
        font_write(f.stem, pack_bmf(f))
      end
    end
  end

  active_font_idx = 1
  cur_font = fonts[1]
  cur_char = 65
end

local function select_font(idx)
  if idx >= 1 and idx <= #fonts then
    active_font_idx = idx
    cur_font = fonts[idx]
  end
end

local function get_glyph(c)
  if not cur_font.glyphs[c] then
    cur_font.glyphs[c] = {}
    for y = 1, cur_font.ch do
      cur_font.glyphs[c][y] = 0
    end
  end
  return cur_font.glyphs[c]
end

local function get_pixel(c, x, y)
  local g = get_glyph(c)
  local row = g[y] or 0
  local shift = cur_font.cw - x
  return (row & (1 << shift)) ~= 0
end

local function set_pixel(c, x, y, val)
  local g = get_glyph(c)
  local row = g[y] or 0
  local shift = cur_font.cw - x
  if val then
    row = row | (1 << shift)
  else
    row = row & ~(1 << shift)
  end
  g[y] = row
end

local function clear_glyph()
  local g = get_glyph(cur_char)
  for y = 1, cur_font.ch do
    g[y] = 0
  end
  set_notice("Glyph cleared")
end

local function invert_glyph()
  local g = get_glyph(cur_char)
  local mask = (1 << cur_font.cw) - 1
  for y = 1, cur_font.ch do
    g[y] = (g[y] ~ mask) & mask
  end
  set_notice("Glyph inverted")
end

local function flip_h()
  local g = get_glyph(cur_char)
  for y = 1, cur_font.ch do
    local r = g[y]
    local nr = 0
    for x = 1, cur_font.cw do
      if (r & (1 << (cur_font.cw - x))) ~= 0 then
        nr = nr | (1 << (x - 1))
      end
    end
    g[y] = nr
  end
  set_notice("Flipped horizontally")
end

local function flip_v()
  local g = get_glyph(cur_char)
  local top, bot = 1, cur_font.ch
  while top < bot do
    g[top], g[bot] = g[bot], g[top]
    top = top + 1
    bot = bot - 1
  end
  set_notice("Flipped vertically")
end

local function shift_glyph(dx, dy)
  local g = get_glyph(cur_char)
  local ng = {}
  local mask = (1 << cur_font.cw) - 1
  for y = 1, cur_font.ch do
    local sy = y - dy
    if sy >= 1 and sy <= cur_font.ch then
      local row = g[sy]
      if dx > 0 then
        row = (row >> dx) & mask
      elseif dx < 0 then
        row = (row << (-dx)) & mask
      end
      ng[y] = row
    else
      ng[y] = 0
    end
  end
  for y = 1, cur_font.ch do
    g[y] = ng[y]
  end
end

local function copy_glyph()
  local g = get_glyph(cur_char)
  clipboard = {}
  for y = 1, cur_font.ch do
    clipboard[y] = g[y]
  end
  set_notice("Copied glyph 0x" .. string.format("%02X", cur_char))
end

local function paste_glyph()
  if not clipboard then
    set_notice("Clipboard empty")
    return
  end
  local g = get_glyph(cur_char)
  for y = 1, cur_font.ch do
    g[y] = clipboard[y] or 0
  end
  set_notice("Pasted into glyph 0x" .. string.format("%02X", cur_char))
end

local function export_font()
  save({ active_idx = active_font_idx, fonts = fonts })
  local stem = cur_font.stem or (cur_font.name:gsub("%s+", "_"):lower():sub(1, 12))
  local data = pack_bmf(cur_font)
  if font_write then
    local ok, err = font_write(stem, data)
    if ok then
      set_notice("Salcato in /bmf/" .. stem .. ".bmf!")
      return
    end
  end
  set_notice("Salvato nei dati utente (/bm/save)!")
end

local function create_new_font()
  local ncw, nch = 8, 16
  if new_font_size == "8x8" then ncw, nch = 8, 8
  elseif new_font_size == "6x12" then ncw, nch = 6, 12 end
  
  local base_hex = HEX_INTER_8X16
  if new_font_base == "terminus" then base_hex = HEX_ORIG_8X16
  elseif new_font_base == "6x12" then base_hex = HEX_6X12 end
  
  local gl = parse_hex_glyphs(base_hex, nch)
  local stem = "font_" .. (#fonts + 1)
  local nf = {
    name = "Custom " .. (#fonts + 1),
    stem = stem,
    cw = ncw,
    ch = nch,
    glyphs = gl
  }
  table.insert(fonts, nf)
  active_font_idx = #fonts
  cur_font = nf
  if font_write then
    font_write(stem, pack_bmf(nf))
  end
  new_modal_open = false
  set_notice("Creato /bmf/" .. stem .. ".bmf!")
end

-- Layout Constants
local GRID_X = 20
local GRID_Y = 40
local GRID_MAX_W = 128
local GRID_MAX_H = 256

local SHEET_X = 180
local SHEET_Y = 40
local SHEET_COLS = 16
local SHEET_ROWS = 16
local SHEET_CELL_W = 18
local SHEET_CELL_H = 18

local TOOLS_X = 490
local TOOLS_Y = 40

function _init()
  init_fonts()
end

function _update()
  if notice_timer > 0 then
    notice_timer = notice_timer - 1
  end

  local mx, my, mb = mouse()
  local click = mousep(1)
  local rclick = mousep(2)
  local hold = mb & 1 ~= 0
  local rhold = mb & 2 ~= 0

  -- Modal: New Font Creation
  if new_modal_open then
    if click then
      -- Modal window: 200, 80, 240, 200
      local mw, mh = 240, 200
      local mx0, my0 = (640 - mw) / 2, (360 - mh) / 2
      -- Dimension options
      if mx >= mx0 + 20 and mx <= mx0 + 80 and my >= my0 + 50 and my <= my0 + 72 then new_font_size = "8x16" end
      if mx >= mx0 + 90 and mx <= mx0 + 150 and my >= my0 + 50 and my <= my0 + 72 then new_font_size = "8x8" end
      if mx >= mx0 + 160 and mx <= mx0 + 220 and my >= my0 + 50 and my <= my0 + 72 then new_font_size = "6x12" end
      -- Template options
      if mx >= mx0 + 20 and mx <= mx0 + 110 and my >= my0 + 100 and my <= my0 + 122 then new_font_base = "inter" end
      if mx >= mx0 + 120 and mx <= mx0 + 210 and my >= my0 + 100 and my <= my0 + 122 then new_font_base = "terminus" end
      -- Action buttons
      if mx >= mx0 + 20 and mx <= mx0 + 105 and my >= my0 + 150 and my <= my0 + 180 then
        create_new_font()
      elseif mx >= mx0 + 125 and mx <= mx0 + 210 and my >= my0 + 150 and my <= my0 + 180 then
        new_modal_open = false
      end
    end
    return
  end
  
  -- Handle Dropdown menu clicks
  if dropdown_open then
    if click then
      local dy0 = 30
      local item_h = 20
      local handled = false
      for idx, f in ipairs(fonts) do
        local iy = dy0 + (idx - 1) * item_h
        if mx >= 14 and mx <= 200 and my >= iy and my < iy + item_h then
          select_font(idx)
          dropdown_open = false
          set_notice("Selezionato " .. f.name)
          handled = true
          break
        end
      end
      if not handled then
        local action_y = dy0 + #fonts * item_h + 6
        if mx >= 14 and mx <= 200 and my >= action_y and my < action_y + item_h then
          dropdown_open = false
          new_modal_open = true
          handled = true
        elseif mx >= 14 and mx <= 200 and my >= action_y + item_h and my < action_y + item_h * 2 then
          dropdown_open = false
          export_font()
          handled = true
        else
          dropdown_open = false
        end
      end
    end
    return
  end
  
  -- Top Dropdown button click
  if click and mx >= 14 and mx <= 180 and my >= 4 and my <= 24 then
    dropdown_open = true
    return
  end
  
  -- Interactive Scale buttons click
  if click then
    local sx0 = TOOLS_X + 80
    local sy0 = TOOLS_Y
    if mx >= sx0 and mx < sx0 + 26 and my >= sy0 and my < sy0 + 16 then preview_scale = 1 end
    if mx >= sx0 + 28 and mx < sx0 + 54 and my >= sy0 and my < sy0 + 16 then preview_scale = 2 end
    if mx >= sx0 + 56 and mx < sx0 + 82 and my >= sy0 and my < sy0 + 16 then preview_scale = 3 end
  end

  -- Grid Drawing
  local cell_size = math.min(math.floor(GRID_MAX_W / cur_font.cw), math.floor(GRID_MAX_H / cur_font.ch))
  local grid_w = cur_font.cw * cell_size
  local grid_h = cur_font.ch * cell_size
  if mx >= GRID_X and mx < GRID_X + grid_w and my >= GRID_Y and my < GRID_Y + grid_h then
    local gx = math.floor((mx - GRID_X) / cell_size) + 1
    local gy = math.floor((my - GRID_Y) / cell_size) + 1
    if hold then
      set_pixel(cur_char, gx, gy, true)
    elseif rhold then
      set_pixel(cur_char, gx, gy, false)
    end
  end

  -- Sheet Selection
  if mx >= SHEET_X and mx < SHEET_X + SHEET_COLS * SHEET_CELL_W and
     my >= SHEET_Y and my < SHEET_Y + SHEET_ROWS * SHEET_CELL_H then
    local col = math.floor((mx - SHEET_X) / SHEET_CELL_W)
    local row = math.floor((my - SHEET_Y) / SHEET_CELL_H)
    local sel = row * 16 + col
    if click then
      cur_char = sel
    end
  end

  -- Tool buttons
  if click then
    local bx, by = TOOLS_X, TOOLS_Y + 54
    local bw, bh = 42, 16
    local gap = 4
    if mx >= bx and mx < bx + bw and my >= by and my < by + bh then clear_glyph() end
    if mx >= bx + bw + gap and mx < bx + (bw + gap) * 2 and my >= by and my < by + bh then invert_glyph() end
    if mx >= bx + (bw + gap) * 2 and mx < bx + (bw + gap) * 3 and my >= by and my < by + bh then flip_h() end
    if mx >= bx + (bw + gap) * 3 and mx < bx + (bw + gap) * 4 and my >= by and my < by + bh then flip_v() end

    -- Shift arrows
    local ax, ay = bx + 28, by + 24
    if mx >= ax + 14 and mx < ax + 28 and my >= ay and my < ay + 14 then shift_glyph(0, -1) end
    if mx >= ax and mx < ax + 14 and my >= ay + 14 and my < ay + 28 then shift_glyph(-1, 0) end
    if mx >= ax + 28 and mx < ax + 42 and my >= ay + 14 and my < ay + 28 then shift_glyph(1, 0) end
    if mx >= ax + 14 and mx < ax + 28 and my >= ay + 28 and my < ay + 42 then shift_glyph(0, 1) end

    -- Copy / Paste
    local cx, cy = bx + 78, ay + 10
    if mx >= cx and mx < cx + 32 and my >= cy and my < cy + 18 then copy_glyph() end
    if mx >= cx + 36 and mx < cx + 68 and my >= cy and my < cy + 18 then paste_glyph() end

    -- Save / Export button
    local ex, ey = TOOLS_X + 70, TOOLS_Y + 118
    if mx >= ex and mx < ex + 76 and my >= ey and my < ey + 20 then
      export_font()
    end
  end

  -- Typed keys
  local k = keyp()
  while k do
    if k == "\t" then
      dropdown_open = not dropdown_open
    elseif k == "^s" or k == "ctrl s" then
      export_font()
    elseif k == "^c" or k == "ctrl c" then
      copy_glyph()
    elseif k == "^v" or k == "ctrl v" then
      paste_glyph()
    elseif k == "1" then
      preview_scale = 1
    elseif k == "2" then
      preview_scale = 2
    elseif k == "3" then
      preview_scale = 3
    elseif k == "left" then
      cur_char = (cur_char - 1) & 0xFF
    elseif k == "right" then
      cur_char = (cur_char + 1) & 0xFF
    elseif k == "up" then
      cur_char = (cur_char - 16) & 0xFF
    elseif k == "down" then
      cur_char = (cur_char + 16) & 0xFF
    end
    k = keyp()
  end
end

local function draw_glyph_scaled(c, dx, dy, scale, col)
  local g = get_glyph(c)
  for y = 1, cur_font.ch do
    local r = g[y] or 0
    for x = 1, cur_font.cw do
      if (r & (1 << (cur_font.cw - x))) ~= 0 then
        if scale == 1 then
          pset(dx + x - 1, dy + y - 1, col)
        else
          rectfill(dx + (x - 1) * scale, dy + (y - 1) * scale, scale, scale, col)
        end
      end
    end
  end
end

function _draw()
  cls(C.bg)

  -- Header
  rectfill(0, 0, 640, 28, C.panel)
  line(0, 28, 639, 28, C.border)
  
  -- Dropdown Menu Button
  rectfill(14, 4, 166, 20, dropdown_open and C.btn_hi or C.btn)
  rect(14, 4, 166, 20, dropdown_open and C.cyan or C.border)
  print("Font: " .. cur_font.name .. "  v", 20, 6, dropdown_open and C.cyan or C.btn_text)
  
  -- Glyph info
  local char_rep = (cur_char >= 32 and cur_char <= 126) and string.char(cur_char) or "?"
  local info_str = string.format("Glyph: '%s'  Dec: %d  Hex: 0x%02X", char_rep, cur_char, cur_char)
  print(info_str, 200, 6, C.white)

  -- Notice badge
  if notice_timer > 0 then
    print(notice, 440, 6, C.cyan)
  end

  -- Left Panel: Large Glyph Editor
  local cell_size = math.min(math.floor(GRID_MAX_W / cur_font.cw), math.floor(GRID_MAX_H / cur_font.ch))
  local grid_w = cur_font.cw * cell_size
  local grid_h = cur_font.ch * cell_size

  rectfill(GRID_X - 6, GRID_Y - 6, grid_w + 12, grid_h + 12, C.panel)
  rect(GRID_X - 6, GRID_Y - 6, grid_w + 12, grid_h + 12, C.border)

  for y = 1, cur_font.ch do
    for x = 1, cur_font.cw do
      local on = get_pixel(cur_char, x, y)
      local px = GRID_X + (x - 1) * cell_size
      local py = GRID_Y + (y - 1) * cell_size
      rectfill(px, py, cell_size - 1, cell_size - 1, on and C.pixel_on or C.pixel_off)
    end
  end

  -- Baseline guide
  line(GRID_X, GRID_Y + grid_h, GRID_X + grid_w, GRID_Y + grid_h, C.accent)

  -- Center Panel: Code Page 437 Sheet
  rectfill(SHEET_X - 6, SHEET_Y - 6, SHEET_COLS * SHEET_CELL_W + 12, SHEET_ROWS * SHEET_CELL_H + 12, C.panel)
  rect(SHEET_X - 6, SHEET_Y - 6, SHEET_COLS * SHEET_CELL_W + 12, SHEET_ROWS * SHEET_CELL_H + 12, C.border)

  for r = 0, SHEET_ROWS - 1 do
    for col = 0, SHEET_COLS - 1 do
      local ch_idx = r * 16 + col
      local cx = SHEET_X + col * SHEET_CELL_W
      local cy = SHEET_Y + r * SHEET_CELL_H

      if ch_idx == cur_char then
        rect(cx - 1, cy - 1, SHEET_CELL_W + 1, SHEET_CELL_H + 1, C.yellow)
      end

      local gx = cx + math.floor((SHEET_CELL_W - cur_font.cw) / 2)
      local gy = cy + math.floor((SHEET_CELL_H - cur_font.ch) / 2)
      draw_glyph_scaled(ch_idx, gx, gy, 1, (ch_idx == cur_char) and C.yellow or C.text)
    end
  end

  -- Right Panel: Tools and Previews
  rectfill(TOOLS_X - 6, TOOLS_Y - 6, 148, 150, C.panel)
  rect(TOOLS_X - 6, TOOLS_Y - 6, 148, 150, C.border)

  -- Scale selectors
  print("Scale:", TOOLS_X, TOOLS_Y + 4, C.dim)
  local sx0 = TOOLS_X + 46
  local sy0 = TOOLS_Y + 1
  for s = 1, 3 do
    local bx = sx0 + (s - 1) * 28
    rectfill(bx, sy0, 24, 14, (preview_scale == s) and C.cyan or C.btn)
    rect(bx, sy0, 24, 14, (preview_scale == s) and C.white or C.border)
    print(s .. "x", bx + 5, sy0 + 2, (preview_scale == s) and C.black or C.btn_text)
  end

  -- Glyph zoom samples
  draw_glyph_scaled(cur_char, TOOLS_X, TOOLS_Y + 24, 1, C.cyan)
  draw_glyph_scaled(cur_char, TOOLS_X + 16, TOOLS_Y + 22, 2, C.white)
  draw_glyph_scaled(cur_char, TOOLS_X + 40, TOOLS_Y + 20, 3, C.white)

  -- Operation buttons
  local bx, by = TOOLS_X, TOOLS_Y + 54
  local bw, bh = 42, 16
  local gap = 4
  local ops = { "Clear", C.btn }, { "Invert", C.btn }, { "FlipH", C.btn }, { "FlipV", C.btn }
  for i, op in ipairs(ops) do
    local ox = bx + (i - 1) * (bw + gap)
    if i > 2 then ox = bx + (i - 3) * (bw + gap) end
    local oy = by
    if i > 2 then oy = by + 20 end
    rectfill(ox, oy, bw, bh, op[2])
    rect(ox, oy, bw, bh, C.border)
    print(op[1], ox + 4, oy + 4, C.btn_text)
  end

  -- Shift D-pad
  local ax, ay = bx + 96, by
  rectfill(ax + 14, ay, 14, 14, C.btn); rect(ax + 14, ay, 14, 14, C.border); print("^", ax + 19, ay + 2, C.btn_text)
  rectfill(ax, ay + 14, 14, 14, C.btn); rect(ax, ay + 14, 14, 14, C.border); print("<", ax + 4, ay + 16, C.btn_text)
  rectfill(ax + 28, ay + 14, 14, 14, C.btn); rect(ax + 28, ay + 14, 14, 14, C.border); print(">", ax + 33, ay + 16, C.btn_text)
  rectfill(ax + 14, ay + 28, 14, 14, C.btn); rect(ax + 14, ay + 28, 14, 14, C.border); print("v", ax + 19, ay + 30, C.btn_text)

  -- Copy / Paste buttons
  local cx, cy = bx + 50, by + 42
  rectfill(cx, cy, 38, 16, C.btn); rect(cx, cy, 38, 16, C.border); print("Copy", cx + 6, cy + 4, C.btn_text)
  rectfill(cx + 42, cy, 38, 16, C.btn); rect(cx + 42, cy, 38, 16, C.border); print("Paste", cx + 4, cy + 4, C.btn_text)

  -- Save / Export button
  local ex, ey = TOOLS_X, TOOLS_Y + 118
  rectfill(ex, ey, 136, 20, C.btn_hi)
  rect(ex, ey, 136, 20, C.green)
  print("Salva in /bmf", ex + 24, ey + 5, C.green)

  -- Live Preview box
  local pv_x = TOOLS_X - 6
  local pv_y = 196
  rectfill(pv_x, pv_y, 148, 136, C.panel)
  rect(pv_x, pv_y, 148, 136, C.border)
  print("Live Preview (" .. preview_scale .. "x):", pv_x + 6, pv_y + 6, C.dim)

  local preview_lines = {
    "The quick fox",
    "jumps over lazy",
    "0123456789",
    "Hello BareMetal!",
  }
  local py = pv_y + 22
  for _, line_txt in ipairs(preview_lines) do
    local px = pv_x + 6
    for i = 1, #line_txt do
      local ch_code = line_txt:byte(i)
      draw_glyph_scaled(ch_code, px, py, preview_scale, C.white)
      px = px + cur_font.cw * preview_scale
      if px >= pv_x + 140 then break end
    end
    py = py + (cur_font.ch + 2) * preview_scale
    if py >= pv_y + 130 then break end
  end

  -- Dropdown Menu Overlay
  if dropdown_open then
    local dy0 = 26
    local dw = 190
    local item_h = 20
    local dh = #fonts * item_h + 54
    rectfill(14, dy0, dw, dh, C.panel_hi)
    rect(14, dy0, dw, dh, C.cyan)
    for idx, f in ipairs(fonts) do
      local iy = dy0 + (idx - 1) * item_h
      if idx == active_font_idx then
        rectfill(16, iy + 1, dw - 4, item_h - 2, C.btn_hi)
        print("> " .. f.name .. " (" .. f.cw .. "x" .. f.ch .. ")", 20, iy + 4, C.cyan)
      else
        print("  " .. f.name .. " (" .. f.cw .. "x" .. f.ch .. ")", 20, iy + 4, C.text)
      end
    end
    -- Dropdown action buttons
    local action_y = dy0 + #fonts * item_h + 6
    line(14, action_y - 3, 14 + dw, action_y - 3, C.border)
    print("+ Nuovo Font...", 24, action_y + 2, C.yellow)
    print("v Salva in /bmf", 24, action_y + item_h + 2, C.green)
  end

  -- Modal Window: New Font
  if new_modal_open then
    rectfill(0, 0, 640, 360, 0x88000000) -- backdrop
    local mw, mh = 240, 190
    local mx0, my0 = (640 - mw) / 2, (360 - mh) / 2
    rectfill(mx0, my0, mw, mh, C.panel)
    rect(mx0, my0, mw, mh, C.cyan)
    print("Crea Nuovo Font", mx0 + 60, my0 + 12, C.white)

    print("Dimensioni glifo:", mx0 + 20, my0 + 36, C.dim)
    local sizes = { "8x16", 20 }, { "8x8", 90 }, { "6x12", 160 }
    for _, s in ipairs(sizes) do
      local bx = mx0 + s[2]
      rectfill(bx, my0 + 52, 60, 20, (new_font_size == s[1]) and C.cyan or C.btn)
      rect(bx, my0 + 52, 60, 20, C.border)
      print(s[1], bx + 14, my0 + 56, (new_font_size == s[1]) and C.black or C.btn_text)
    end

    print("Template base:", mx0 + 20, my0 + 84, C.dim)
    local templates = { "Inter", "inter", 20 }, { "Terminus", "terminus", 120 }
    for _, t in ipairs(templates) do
      local bx = mx0 + t[3]
      rectfill(bx, my0 + 100, 90, 20, (new_font_base == t[2]) and C.cyan or C.btn)
      rect(bx, my0 + 100, 90, 20, C.border)
      print(t[1], bx + 16, my0 + 104, (new_font_base == t[2]) and C.black or C.btn_text)
    end

    -- Confirm / Cancel
    rectfill(mx0 + 20, my0 + 145, 90, 26, C.green)
    print("Crea", mx0 + 50, my0 + 152, C.black)

    rectfill(mx0 + 130, my0 + 145, 90, 26, C.btn_hi)
    rect(mx0 + 130, my0 + 145, 90, 26, C.border)
    print("Annulla", mx0 + 150, my0 + 152, C.btn_text)
  end

  -- Bottom key hints
  rectfill(0, 342, 640, 18, C.panel)
  line(0, 342, 639, 342, C.border)
  print("[Mouse] Edita   [Tab] Menu Font   [1/2/3] Zoom   [Ctrl+S] Salva in /bmf", 14, 346, C.dim)
end
